import itertools
def comps(edges, n):
    p=list(range(n))
    def f(x):
        while p[x]!=x: p[x]=p[p[x]]; x=p[x]
        return x
    for a,b in edges:
        ra,rb=f(a),f(b)
        if ra!=rb: p[max(ra,rb)]=min(ra,rb)
    groups={}
    for i in range(n): groups.setdefault(f(i),[]).append(i)
    return sorted(tuple(v) for v in groups.values())

def brute(n):
    pairs=[(i,j) for i in range(n) for j in range(i+1,n)]
    bad=0
    for bits in range(1<<len(pairs)):
        E=[pairs[k] for k in range(len(pairs)) if bits>>k & 1]
        adj={i:set() for i in range(n)}
        for a,b in E: adj[a].add(b); adj[b].add(a)
        # only consider nodes that have at least one edge (cores)
        nodes=[i for i in range(n) if adj[i]]
        G=comps([(a,b) for a,b in E], n)
        G=[tuple(x for x in c if x in set(nodes)) for c in G]
        G=sorted(c for c in G if c)
        Hedges=[]
        for i in nodes:
            m=min(adj[i])
            Hedges.append((i,m))
        H=comps(Hedges, n)
        H=[tuple(x for x in c if x in set(nodes)) for c in H]
        H=sorted(c for c in H if c)
        if G!=H:
            bad+=1
            if bad<3: print('COUNTER n=%d'%n, E, 'G',G,'H',H)
    return bad
for n in (4,5,6):
    print('n=',n,'bad',brute(n))
